//! Logo Cutout fixtures generated by the pinned original renderer.
use filmcraft_project::{Param,ParamValue};use filmcraft_render::{effects::{apply,FxCtx},image::Image};use serde_json::json;
fn main(){let mut cases=vec![];
for(w,h)in[(1,7),(7,1),(6,4),(18,10)]{for background in 0..3u32{for threshold in[0.,5.,100.]{for softness in[0.,10.,100.]{for unmultiply in[false,true]{for invert in[false,true]{for color in[[1f32;4],[0.25,0.75,0.125,0.]]{
let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1],[255,255,255,128],[0,0,0,255]][(i+i/w)%7]).collect();let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;[filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[1]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[2]as f32/255.)*a,a]}).collect();let mut image=Image{w,h,px};let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="logo_cutout").unwrap().instance();
for(id,value)in[("background",ParamValue::Choice(background)),("color",ParamValue::Color(color)),("threshold",ParamValue::Float(threshold)),("softness",ParamValue::Float(softness)),("unmultiply",ParamValue::Bool(unmultiply)),("invert",ParamValue::Bool(invert))]{effect.params.insert(id.into(),Param::new(value));}
let cx=FxCtx{t:filmcraft_time::Tick(0),px_scale:1.,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut image,&effect,&cx);cases.push(json!({"width":w,"height":h,"rgba":rgba,"parameters":{"background":background,"color":color,"threshold":threshold,"softness":softness,"unmultiply":unmultiply,"invert":invert},"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
}}}}}}}
let mut media=vec![];
for background in 0..3u32 {for unmultiply in [false,true] {for invert in [false,true] {for tick in [0u64,250000,500000] {
let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12{255}else{32};[v,v,v,128]}).collect();let mut frames=vec![];
for index in 0..(1000000-tick).div_ceil(100000) {let local=(tick+index*100000).min(500000);let t=local as f64/500000.;let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;let v=filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a;[v,v,v,a]}).collect();let mut frame=Image{w:16,h:16,px};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="logo_cutout").unwrap().instance();
for (id,value) in [("background",ParamValue::Choice(background)),("unmultiply",ParamValue::Bool(unmultiply)),("invert",ParamValue::Bool(invert)),("threshold",ParamValue::Float(5.+70.*t)),("softness",ParamValue::Float(10.+90.*t)),("color",ParamValue::Color([(1.-0.75*t)as f32,(1.-0.25*t)as f32,(1.-0.875*t)as f32,(1.-t)as f32]))] {e.params.insert(id.into(),Param::new(value));}
let cx=FxCtx{t:filmcraft_time::Tick(local as i64),px_scale:1.,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut frame,&e,&cx);frames.push(frame.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());}
media.push(json!({"localTick":tick,"parameters":{"background":background,"unmultiply":unmultiply,"invert":invert},"rgba":rgba,"bits":frames[0],"frames":frames}));
}}}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));}
